(() => {
  const OPERATION = 2;
  const WASM_BASE64 = '';
  let wasmPromise;

  const fromBase64 = text => {
    const raw = atob(text);
    const bytes = new Uint8Array(raw.length);
    for (let i = 0; i < raw.length; i++) bytes[i] = raw.charCodeAt(i);
    return bytes;
  };
  const utf8Encode = text => {
    const bytes = [];
    for (const character of String(text)) {
      const code = character.codePointAt(0);
      if (code <= 0x7f) bytes.push(code);
      else if (code <= 0x7ff) bytes.push(0xc0 | (code >> 6), 0x80 | (code & 0x3f));
      else if (code <= 0xffff) bytes.push(0xe0 | (code >> 12), 0x80 | ((code >> 6) & 0x3f), 0x80 | (code & 0x3f));
      else bytes.push(0xf0 | (code >> 18), 0x80 | ((code >> 12) & 0x3f), 0x80 | ((code >> 6) & 0x3f), 0x80 | (code & 0x3f));
    }
    return new Uint8Array(bytes);
  };
  const utf8Decode = bytes => {
    let text = '';
    for (let i = 0; i < bytes.length;) {
      const first = bytes[i++];
      if (first < 0x80) text += String.fromCharCode(first);
      else if (first < 0xe0) text += String.fromCharCode(((first & 0x1f) << 6) | (bytes[i++] & 0x3f));
      else if (first < 0xf0) text += String.fromCharCode(((first & 0xf) << 12) | ((bytes[i++] & 0x3f) << 6) | (bytes[i++] & 0x3f));
      else {
        const code = ((first & 7) << 18) | ((bytes[i++] & 0x3f) << 12) | ((bytes[i++] & 0x3f) << 6) | (bytes[i++] & 0x3f);
        text += String.fromCodePoint(code);
      }
    }
    return text;
  };
  const loadWasm = () => {
    if (!wasmPromise) wasmPromise = WebAssembly.instantiate(fromBase64(WASM_BASE64), {});
    return wasmPromise;
  };
  const processBody = async body => {
    const input = utf8Encode(body);
    const request = new Uint8Array(input.length + 1);
    request[0] = OPERATION;
    request.set(input, 1);
    const result = await loadWasm();
    const exports = result.instance.exports;
    const pointer = exports.alloc(request.length);
    new Uint8Array(exports.memory.buffer, pointer, request.length).set(request);
    const outputPointer = exports.process(pointer, request.length);
    const outputLength = exports.output_len();
    const output = new Uint8Array(exports.memory.buffer, outputPointer, outputLength).slice();
    exports.dealloc(pointer, request.length);
    return utf8Decode(output);
  };

  if (!$response || !$response.body) return $done({});
  processBody($response.body).then(body => {
    if (body === $response.body) return $done({});
    $done({ body });
  }).catch(error => {
    console.log('my_page_wasm: ' + error.message);
    $done({});
  });
})();
